import { FC, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Checkbox, Drawer, DrawerProps, Flex, Typography } from 'antd';
import cn from 'classnames';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import PlusRectIcon from 'assets/images/icons/plus-rect.svg?react';
import { useBrand, useBrandSlice } from 'entities/Brand';
import { MOCK_COLLECTIONS } from 'shared/consts/MOCK_FOR_CATALOG';
import { NoResults } from 'shared/ui';

import styles from './SaveToAutomationDrawer.module.scss';

interface ISaveToAutomationDrawerProps extends DrawerProps {}

export const SaveToAutomationDrawer: FC<ISaveToAutomationDrawerProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const automations = MOCK_COLLECTIONS; //TODO: get from api
	const { saveToAutomation } = useBrand();
	const { isOpenSaveToAutomationsDrawer, setIsOpenSaveToAutomationsDrawer, setIsOpenCreateAutomationDrawer } =
		useBrandSlice();
	const [selected, setSelected] = useState<string[]>([]);

	const selectAutomation = (id: string) => {
		const newSelected = selected.concat();
		if (newSelected.includes(id)) {
			const index = newSelected.indexOf(id);
			newSelected.splice(index, 1);
		} else {
			newSelected.push(id);
		}
		setSelected(newSelected);
	};

	return (
		<Drawer
			title={t('Добавить задание в автоматизацию')}
			open={isOpenSaveToAutomationsDrawer}
			onClose={() => setIsOpenSaveToAutomationsDrawer(false)}
			destroyOnHidden
			placement="bottom"
			{...props}
			className={cn(className, styles.saveToAutomationDrawer)}>
			<Flex gap={8} vertical>
				{automations.length ? (
					<>
						<Flex gap={4} className={styles.saveToAutomationDrawer__list}>
							{automations.map((automation) => (
								<Button
									className={cn(
										styles.saveToAutomationDrawer__btn,
										selected.includes(automation.id) && styles.saveToAutomationDrawer__btn_checked,
									)}
									onClick={() => selectAutomation(automation.id)}
									key={automation.id}>
									<Flex gap={4} align="flex-start" className={styles.saveToAutomationDrawer__name}>
										<span className={styles.saveToAutomationDrawer__lineClamp}>{automation.name}</span>
										<Checkbox checked={selected.includes(automation.id)} />
									</Flex>
									<Typography.Text type="secondary" className={styles.saveToAutomationDrawer__subText}>
										{t('Постов')}: {automation.items.length}
									</Typography.Text>
									<Flex gap={4} align="center">
										<img
											className={styles.saveToAutomationDrawer__icon}
											src={automation.icon}
											alt={''}
											width={28}
											height={28}
										/>
										<Typography.Text type="secondary" className={styles.saveToAutomationDrawer__subText}>
											{automation.channelName}
										</Typography.Text>
									</Flex>
								</Button>
							))}
							<Button
								className={styles.saveToAutomationDrawer__btn}
								onClick={() => setIsOpenCreateAutomationDrawer(true)}>
								{t('Новая коллекция')}
								<PlusRectIcon className={styles.saveToAutomationDrawer__icon} width={28} height={28} />
							</Button>
						</Flex>
						<Button type="primary" onClick={() => saveToAutomation(selected)}>
							{t('Добавить')}
						</Button>
					</>
				) : (
					<>
						<NoResults
							text={t('Нет автоматизаций')}
							subtext={t('Вы пока не добавили еще ни одного поста и не создали ни одной коллекции')}
						/>
						<Button
							icon={<PlusIcon />}
							variant="outlined"
							color="primary"
							onClick={() => setIsOpenCreateAutomationDrawer(true)}>
							{t('Новая автоматизация')}
						</Button>
					</>
				)}
			</Flex>
		</Drawer>
	);
};
