import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Tag, Typography } from 'antd';
import cn from 'classnames';

// import { SaveToAutomationBtn } from 'entities/Automation';
import { type AdvCampaignRead, EPaymentModel, EPaymentModelMap, useBrandSlice } from 'entities/Brand';
import { EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

// import { AutomationBtnIcon } from 'shared/ui';
import styles from './AdvCampaignCardForBrand.module.scss';

interface IAdvCampaignCardForBrandProps extends HTMLAttributes<HTMLDivElement> {
	advCampaign: AdvCampaignRead;
}

export const AdvCampaignCardForBrand: FC<IAdvCampaignCardForBrandProps> = ({ className, advCampaign, ...props }) => {
	const paymentModel = EPaymentModel.CPA; //TODO: get from api
	// const hasAutomation = Math.random() > 0.5; //TODO: get from api
	const { t } = useTranslation();
	const { setIsOpenDetailsPopup, setAdvCampaign, setVisitedAdvCampaign, visitedAdvCampaigns } = useBrandSlice();

	const handleAdvCampaignClick = () => {
		sendYmEvent('click_detail_advCampaign', { page_screen: EYmPageScreen.BRAND_SCREEN });
		setAdvCampaign(advCampaign);
		setVisitedAdvCampaign(advCampaign.uuid);
		setIsOpenDetailsPopup(true);
	};

	return (
		<>
			<Flex vertical {...props} className={cn(className, styles.advCampaignCard)} onClick={handleAdvCampaignClick}>
				<img className={styles.advCampaignCard__image} src={advCampaign.image} alt={advCampaign.name} />
				<Flex gap={2} vertical className={styles.advCampaignCard__body}>
					<Typography.Paragraph
						className={styles.advCampaignCard__lineClamp}
						type={visitedAdvCampaigns.includes(advCampaign.uuid) ? 'secondary' : undefined}
						ellipsis={{
							rows: 3,
						}}>
						{advCampaign.name}
					</Typography.Paragraph>
					<Typography.Text className={styles.advCampaignCard__rate} type="secondary">
						{t('Ставка')}{' '}
						{Object.values(advCampaign.grouped_rates)
							.filter((rate) => !!rate)
							.join(', ')}
					</Typography.Text>
					<Tag className={styles.advCampaignCard__tags} color={EPaymentModelMap[paymentModel].color} bordered={false}>
						{EPaymentModelMap[paymentModel].text}
					</Tag>
				</Flex>
				{/*<SaveToAutomationBtn*/}
				{/*	icon={<AutomationBtnIcon hasAutomation={hasAutomation} />}*/}
				{/*	className={styles.advCampaignCard__likeBtn}*/}
				{/*	type="text"*/}
				{/*	hasAutomation={hasAutomation}*/}
				{/*	advCampaign={advCampaign}*/}
				{/*/>*/}
			</Flex>
		</>
	);
};
