import { FC, HTMLAttributes } from 'react';

import { Flex } from 'antd';
import cn from 'classnames';

import { type BrandRead } from 'entities/Brand';

import { BrandDetails } from '../BrandDetails/BrandDetails';
import { BrandHeader } from '../BrandHeader/BrandHeader';

import styles from './BrandInfo.module.scss';

interface IBrandInfoProps extends HTMLAttributes<HTMLDivElement> {
	brand: BrandRead;
}

export const BrandInfo: FC<IBrandInfoProps> = ({ className, brand, ...props }) => {
	return (
		<Flex vertical gap={12} {...props} className={cn(className, styles.brandInfo)}>
			<BrandHeader brand={brand} />
			<BrandDetails brand={brand} />
		</Flex>
	);
};
