import { FC, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Modal, type ModalProps, notification, Segmented, Tag, Typography } from 'antd';
import cn from 'classnames';

// import AutomationIcon from 'assets/images/icons/automation.svg?react';
// import AutomationAddIcon from 'assets/images/icons/automation-add.svg?react';
import CalendarIcon from 'assets/images/icons/calendar-with-clock.svg?react';
// import { SaveToAutomationBtn } from 'entities/Automation';
import {
	EPaymentModel,
	EPaymentModelMap,
	useAdvcampaignsPostsSendToPmCreateMutation,
	useBrand,
	useBrandSlice,
} from 'entities/Brand';
import { COUNTRIES } from 'shared/consts';
import { EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './AdvCampaignDetailsPopup.module.scss';

interface IAdvCampaignDetailsPopupProps extends ModalProps {}

export const AdvCampaignDetailsPopup: FC<IAdvCampaignDetailsPopupProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const paymentModel = EPaymentModel.CPA; //TODO: get from api
	// const hasAutomation = Math.random() > 0.5; //TODO: get from api
	const { handleSendClick } = useBrand();
	const { setIsOpenDetailsPopup, isOpenDetailsPopup, advCampaign } = useBrandSlice();
	const [sendToPm, { isLoading: isSendingToPm, isSuccess: isSentToPmSuccess }] =
		useAdvcampaignsPostsSendToPmCreateMutation();

	// TODO:
	const tariffMap: { [key: string]: string } = {
		fixed: advCampaign?.currency.sign || '',
		percent: '%',
	};

	const detailItems = [
		{
			term: t('Модели оплаты'),
			description: (
				<Flex align="flex-start" gap={8}>
					<Tag color={EPaymentModelMap[EPaymentModel.CPA].color} bordered={false}>
						{EPaymentModelMap[paymentModel].text}
					</Tag>
					<div>
						– {EPaymentModelMap[paymentModel].fullName}
						<br />
						{EPaymentModelMap[paymentModel].description}
					</div>
				</Flex>
			),
		},
		{
			term: t('Ставка'),
			description: (
				<>
					{/*TODO:*/}
					{advCampaign?.actual_rates.map((rate) => (
						<div key={rate.id}>
							{rate.payout_size}
							{tariffMap[rate.type]} – {rate.name}, {rate.description}
						</div>
					))}
				</>
			),
		},
		{ term: t('Гео'), description: advCampaign?.countries?.map((country) => COUNTRIES[country.alpha_2]).join(', ') },
		{
			term: t('Описание платного задания'),
			description: (
				<span
					dangerouslySetInnerHTML={{ __html: advCampaign?.description || '' }}
					className={styles.detailsPopup__innerHtml}
				/>
			),
		},
	];

	const postItems = [
		{
			term: t('Иллюстрация к посту'),
			description: advCampaign?.posts[0]?.images[0]?.image ? (
				<img src={advCampaign.posts[0].images[0].image} alt={advCampaign?.name} className={styles.detailsPopup__img} />
			) : (
				<></>
			),
		},
		{
			term: t('Текст поста'),
			description: (
				<span
					dangerouslySetInnerHTML={{ __html: advCampaign?.posts[0]?.content || '' }}
					className={styles.detailsPopup__innerHtml}
				/>
			),
		},
		{
			term: t('Правила редактирования'),
			description: t('Допускается незначительное изменение, например, смены мужского рода глаголов на женский'),
		},
	];

	const segmentedOptions = [
		{ label: t('Детали'), value: detailItems },
		{
			label: t('Пост'),
			value: postItems,
			...(!advCampaign?.posts.length && {
				disabled: true,
				className: styles.detailsPopup__disabled,
			}),
		},
	];

	const [segment, setSegment] = useState(detailItems);

	const handleSendExampleClick = () => {
		sendYmEvent('click_send_example_post', { page_screen: EYmPageScreen.ADVCAMPAIGN_SCREEN });
		// 	TODO:
		sendToPm(advCampaign?.posts[0]?.uuid || '');
	};

	useEffect(() => {
		if (isSentToPmSuccess) {
			notification.success({
				message: t('Пост успешно отправлен'),
				placement: 'bottom',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	}, [isSentToPmSuccess, t]);

	if (!advCampaign) return null;

	return (
		<Modal
			open={isOpenDetailsPopup}
			onCancel={() => setIsOpenDetailsPopup(false)}
			className={cn(className, styles.detailsPopup)}
			title={advCampaign.name}
			destroyOnHidden
			footer={null}
			classNames={{
				header: styles.detailsPopup__modalHeader,
				content: styles.detailsPopup__modal,
			}}
			{...props}>
			<Segmented
				defaultValue={detailItems}
				options={segmentedOptions}
				onChange={(value) => {
					if (value === postItems) {
						sendYmEvent('click_post_advCampaign', {
							page_screen: EYmPageScreen.ADVCAMPAIGN_SCREEN,
							event_type: 'click_button',
						});
					}
					setSegment(value);
				}}
				block
				className={styles.detailsPopup__segmented}
			/>

			<dl>
				{segment.map((item) => (
					<Flex gap={4} vertical key={item.term} className={styles.detailsPopup__line}>
						<dt>
							<Typography.Text type={'secondary'} className={styles.detailsPopup__dt}>
								{item.term}:
							</Typography.Text>
						</dt>
						<dd>{item.description}</dd>
					</Flex>
				))}
			</dl>

			<Flex gap={4} vertical className={styles.detailsPopup__footer}>
				<Flex gap={4}>
					<Button
						type="primary"
						block
						icon={<CalendarIcon />}
						onClick={handleSendClick}
						disabled={!advCampaign.posts.length}>
						{t('Опубликовать задание')}
					</Button>
					{/*<SaveToAutomationBtn*/}
					{/*	icon={hasAutomation ? <AutomationIcon /> : <AutomationAddIcon />}*/}
					{/*	style={{ flexShrink: 0 }}*/}
					{/*	variant="outlined"*/}
					{/*	color={hasAutomation ? 'primary' : 'default'}*/}
					{/*	hasAutomation={hasAutomation}*/}
					{/*	advCampaign={advCampaign}*/}
					{/*/>*/}
				</Flex>
				<Button
					type="link"
					block
					onClick={handleSendExampleClick}
					disabled={!advCampaign.posts.length}
					loading={isSendingToPm}>
					{t('Отправить пример поста в личку')}
				</Button>
			</Flex>
		</Modal>
	);
};
