import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { message } from 'antd';

import { useSourcesListQuery } from 'entities/Channel';
import { SOURSCES_LIMIT } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { useCommonSlice } from 'shared/hooks';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import { useBrandSlice } from './useBrandSlice';

export const useBrand = () => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const { setIsOpenSaveToAutomationsDrawer, setIsOpenCreateAutomationDrawer, advCampaign, setIsOpenDetailsPopup } =
		useBrandSlice();
	const { setIsOpenFrozenPopup } = useCommonSlice();
	const { data: sourceList } = useSourcesListQuery({ [EPaginationParams.LIMIT]: SOURSCES_LIMIT });

	const createPost = () => {
		// TODO:
		setIsOpenDetailsPopup(false);
		navigate(`/${EMainRoutes.POST}/${EMainRoutes.CREATE}?advCampaignId=${advCampaign?.uuid}`);
	};

	const openFrozenPopup = () => {
		setIsOpenDetailsPopup(false);
		setIsOpenFrozenPopup(true);
	};

	const handleSendClick = () => {
		sendYmEvent('click_publish_task', { page_screen: EYmPageScreen.ADVCAMPAIGN_SCREEN });
		sourceList?.results.length ? createPost() : openFrozenPopup();
	};

	const createNewAutomation = (collectionName: string) => {
		// TODO:
		console.log('created collection', collectionName);
		setIsOpenCreateAutomationDrawer(false);
		message.success({
			content: t('Автоматизация создана'),
		});
	};

	const saveToAutomation = (collectionIds?: string | string[]) => {
		// TODO:
		console.log('save to collection', collectionIds);
		setIsOpenSaveToAutomationsDrawer(false);
		message.success({
			content: t('Задание добавлено в автоматизации'),
		});
	};

	const deleteFromAutomation = () => {
		// TODO:
		console.log('remove post from collection');
		message.info({
			content: t('Задание удалено из автоматизаций'),
		});
	};

	return {
		t,
		setIsOpenSaveToAutomationsDrawer,
		deleteFromAutomation,
		handleSendClick,
		createNewAutomation,
		saveToAutomation,
	};
};
