import { FC, HTMLAttributes } from 'react';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { AdvCampaignCardForBrand, AdvCampaignDetailsPopup } from 'entities/AdvCampaign';
import { CreateAutomationDrawer, SaveToAutomationDrawer } from 'entities/Automation';
import { BrandInfo, useBrandSlice, useBrandsRetrieveQuery } from 'entities/Brand';
import { useBackButton } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { Content, OverlayLoader, Page } from 'shared/ui';

import styles from './Brand.module.scss';

interface IBrandProps extends HTMLAttributes<HTMLDivElement> {}

export const Brand: FC<IBrandProps> = ({ className, ...props }) => {
	const { id } = useParams<{ id: string }>();
	const { data: brand, isLoading } = useBrandsRetrieveQuery(id || '');
	const { isOpenDetailsPopup, isOpenCreateAutomationDrawer, isOpenSaveToAutomationsDrawer } = useBrandSlice();
	useBackButton(`/${EMainRoutes.CATALOG}`);

	return (
		<Page {...props} className={cn(className, styles.brand)}>
			{isLoading && <OverlayLoader />}
			{!!brand && (
				<>
					<BrandInfo brand={brand} />
					<Content filled>
						<div className={styles.brand__postList}>
							{brand.advcampaigns?.map((advCampaign) => (
								<AdvCampaignCardForBrand key={advCampaign.uuid} advCampaign={advCampaign} />
							))}
						</div>
					</Content>
				</>
			)}

			{isOpenDetailsPopup && <AdvCampaignDetailsPopup />}
			{isOpenCreateAutomationDrawer && <CreateAutomationDrawer />}
			{isOpenSaveToAutomationsDrawer && <SaveToAutomationDrawer />}
		</Page>
	);
};

export default Brand;
